def drop(page,files,folder=False):
 page.evaluate('''({files,folder})=>{
 const dt=new DataTransfer();for(const f of files){const bytes=f.b64?Uint8Array.from(atob(f.b64),c=>c.charCodeAt(0)):f.text;dt.items.add(new File([bytes],f.path.split('/').pop(),{type:f.type}));}
 if(folder){const root={name:'导入资料',isDirectory:true,isFile:false,createReader:()=>{let sent=false;return{readEntries:(ok)=>{if(sent)ok([]);else{sent=true;ok(files.map((f,i)=>({name:f.path,isDirectory:false,isFile:true,file:(ok)=>ok(dt.files[i])})))}}}}};Object.defineProperty(dt.items[0],'webkitGetAsEntry',{value:()=>root});for(let i=1;i<dt.items.length;i++)Object.defineProperty(dt.items[i],'webkitGetAsEntry',{value:()=>null});}
 document.body.dispatchEvent(new DragEvent('dragenter',{bubbles:true,dataTransfer:dt}));document.body.dispatchEvent(new DragEvent('dragover',{bubbles:true,cancelable:true,dataTransfer:dt}));document.body.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:dt}));
 }''',{'files':files,'folder':folder})
